import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"Port mapping library","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/port-mapping/docs/index.md"},"headers":[],"relativePath":"tools/port-mapping/docs/index.md","filePath":"tools/port-mapping/docs/index.md","lastUpdated":1791428389000}'),n={name:"tools/port-mapping/docs/index.md"};function o(s,e,p,d,l,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="port-mapping-library" tabindex="-1">Port mapping library <a class="header-anchor" href="#port-mapping-library" aria-label="Permalink to &quot;Port mapping library&quot;">​</a></h1><p><code>@pumpkin-plugins/port-mapping</code> discovers UPnP and NAT-PMP routers and manages leased port mappings. It is independent of Pumpkin APIs and WASI: network operations are supplied through the small <code>Network</code> interface, which also makes the discovery and retry behavior testable with fake routers.</p><h2 id="mapping-lifecycle" tabindex="-1">Mapping lifecycle <a class="header-anchor" href="#mapping-lifecycle" aria-label="Permalink to &quot;Mapping lifecycle&quot;">​</a></h2><p><code>PortMapper</code> discovers a gateway, requests mappings, renews leases, and removes mappings when they are released. UPnP and NAT-PMP discovery can run together; UPnP is preferred when both respond. Mappings can move to another external port when the requested one is unavailable. Failures are retried with increasing delays, and a failed operation triggers router rediscovery.</p><p>The engine is tick-friendly. Network work is represented as yielded steps and advanced through a <code>Task</code>, so callers can make progress without blocking a game tick. Supply a <code>Network</code> adapter that implements datagrams, connections, and dialing for the host environment.</p><h2 id="reachability-limits" tabindex="-1">Reachability limits <a class="header-anchor" href="#reachability-limits" aria-label="Permalink to &quot;Reachability limits&quot;">​</a></h2><p>Port mapping cannot bypass carrier-grade NAT. If the router&#39;s internet-side address is not public, the server remains unreachable through an inbound mapping. A machine with its own public address does not need a router mapping. Callers can provide a router-identification screen to refuse known unsupported hardware before sending mapping commands.</p><p>The package includes fake network and router implementations for deterministic tests; no live router is required to test the mapping state machine.</p>',8)])])}const g=a(n,[["render",o]]);export{h as __pageData,g as default};
